  await start($)
  await $.tool.call({ ...REVIEW, model: 'haiku' })
  await $.tool.call({ ...REVIEW, model: 'haiku', effort: 'low' })

  expect(seen).toEqual([
    { model: 'haiku', effort: 'high', description: 'Review the diff' },
    { model: 'haiku', effort: 'low', description: 'Review the diff' },
